/* From Uiverse.io by csozidev  - Tags: simple, button, light, challenge, simple button */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  display: flex;
  height: 70px;
  width: 205px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: none;
  background: linear-gradient(0deg, #ebedeb, #ffffff);
  border-radius: 15px;
  position: relative;
  box-shadow: 0px 12px 40px 0px rgba(0, 0, 0, 0.3);
}

.__UIV_SCOPE__ .button::before {
  content: "";
  position: absolute;
  width: 96%;
  background: linear-gradient(180deg, #ebedeb, #ffffff);
  height: 80%;
  border-radius: 100px;
  z-index: 5;
}

.__UIV_SCOPE__ button::after {
  content: "";
  position: absolute;
  width: calc(100% + 6px);
  background: linear-gradient(0deg, #7e807e, #e3e6e4);
  height: calc(100% + 6px);
  z-index: -1;
  border-radius: 18px;
  top: -3px;
  left: -3px;
}

.__UIV_SCOPE__ .button svg {
  stroke-linecap: round;
  width: 20px;
  z-index: 10;
}

.__UIV_SCOPE__ .button p {
  white-space: nowrap;
  font-weight: 600;
  font-size: 20px;
  z-index: 10;
}
